// Wake the car at most once an hour, in daytime, when the house could pay for a
// charge but the inverter (which powers only the car) shows no charging. A sleeping
// car cannot report a plug-in, so the charger status goes stale. After a wake the
// driver's next poll (5 min or less) reads the real plug state, and the
// "Tesla Auto-Start Charging" tab starts charging if the car is plugged in.
// Battery/solar thresholds must match that tab's start rules (checked by tests).
const BATTERY_ONLY_SOC = 50;   // strictly above
const SOLAR_MIN_SOC = 20;      // at least
const SOLAR_WATTS = 700;       // strictly above
const CHARGING_WATTS = 300;    // inverter at or above this = car is charging (~600 W at 5 A)
const REPEAT_MINUTES = 60;
const FIRST_HOUR = 8;          // Central time; wakes from 8:00
const LAST_HOUR = 17;          // up to 16:59
const TIME_ZONE = 'America/Chicago';

const quiet = (text, fill = 'grey') => { node.status({fill, shape: 'ring', text}); return null; };

if (msg.error) return quiet('File problem: ' + msg.error.message, 'red');
let car, home;
try {
    car = JSON.parse(msg.cache).response.drive_state;
    home = JSON.parse(msg.payload);
} catch (e) {
    return quiet('Bad JSON: ' + e.message, 'red');
}

const now = Date.now();
const hour = Number(new Intl.DateTimeFormat('en-US', {timeZone: TIME_ZONE, hour: 'numeric', hourCycle: 'h23'}).format(now));
if (hour < FIRST_HOUR || hour >= LAST_HOUR) return quiet('Outside 8 AM-5 PM Central');

const soc = flow.get('BatterySOC'), solar = flow.get('PVPower');
const status = flow.get('EVChargerStatus'), inverter = flow.get('InverterPower');
if (![soc, solar, inverter].every(Number.isFinite) || !Number.isInteger(status)) return quiet('Waiting for Victron readings');
if (inverter >= CHARGING_WATTS) return quiet(`Car charging (${Math.round(inverter)} W)`);
if (!(soc > BATTERY_ONLY_SOC || (soc >= SOLAR_MIN_SOC && solar > SOLAR_WATTS)))
    return quiet(`Not enough battery or solar (${Math.round(soc)}%, ${Math.round(solar)} W)`);
// 1 Connected: the auto-start tab's start command wakes the car itself. 3 Charged: full.
if (status !== 0 && status !== 2) return quiet(`Charger status ${status}; auto-start handles it`);

if (!car || !Number.isFinite(car.latitude) || !Number.isFinite(car.longitude))
    return quiet('No car location in Tesla cache', 'red');
if (!home || !Number.isFinite(home.latitude) || !Number.isFinite(home.longitude) || !Number.isFinite(home.radius_m))
    return quiet('Bad /data/tesla/home-location.json', 'red');
const rad = d => d * Math.PI / 180;
const a = Math.sin(rad(car.latitude - home.latitude) / 2) ** 2 +
    Math.cos(rad(home.latitude)) * Math.cos(rad(car.latitude)) * Math.sin(rad(car.longitude - home.longitude) / 2) ** 2;
const meters = 2 * 6371000 * Math.asin(Math.sqrt(a));
if (meters > home.radius_m) return quiet(`Car away (${(meters / 1000).toFixed(1)} km)`);

const last = context.get('lastWakeAt');
if (last && now - last < REPEAT_MINUTES * 60 * 1000) return quiet(`Waiting ${REPEAT_MINUTES} min since last wake`);

context.set('lastWakeAt', now);
node.status({fill: 'yellow', shape: 'dot', text: `Wake sent (status ${status}, ${Math.round(inverter)} W)`});
msg.payload = '';
return msg;

// stderr from the wake command: append one line to the shared auto-start error log.
const err = String(msg.payload || '').trim();
if (!err) return null;
return {payload: new Date().toISOString() + ' Hourly wake failed: ' + err.replace(/\s+/g, ' ').slice(0, 1000)};
